mapper.select:


del_flag = '0'

    and activity_id = #{activityId}


    and round_id = #{roundId}


    and object_id = #{objectId}


    and reviewer_count = #{reviewerCount}


    and submitted_count = #{submittedCount}


    and calculated_score = #{calculatedScore}


    and calculated_grade = #{calculatedGrade}


    and calculated_rank = #{calculatedRank}


    and evaluation_conclusion = #{evaluationConclusion}


    and conclusion_generated_by = #{conclusionGeneratedBy}


    and conclusion_generated_time = #{conclusionGeneratedTime}


    and result_status = #{resultStatus}


    and generated_by = #{generatedBy}


    and generated_time = #{generatedTime}


    and published_by = #{publishedBy}


    and published_time = #{publishedTime}


    and revoked_by = #{revokedBy}


    and revoked_time = #{revokedTime}


    order by id desc

select o.activity_id as activityId, coalesce(a.round_id, #{roundId}) as roundId, o.id as objectId, o.object_code as objectCode, o.object_name as objectName, count(distinct a.id) as assignedCount, count(distinct case when r.id is not null then a.id end) as submittedCount, round(avg(r.total_score), 2) as calculatedScore from review_object o left join review_assignment a on a.activity_id = o.activity_id and a.object_id = o.id and a.del_flag = '0'
and a.round_id = #{roundId}
left join review_record r on r.assignment_id = a.id and r.del_flag = '0' and r.record_status = 'SUBMITTED' and r.total_score is not null where o.del_flag = '0' and o.activity_id = #{activityId}
and a.round_id is not null
and o.id in
#{objectId}
group by o.activity_id, coalesce(a.round_id, #{roundId}), o.id, o.object_code, o.object_name

select * from ( select res.id as resultId, m.activityId as activityId, act.activity_name as activityName, m.roundId as roundId, rd.round_name as roundName, m.objectId as objectId, o.object_code as objectCode, o.object_name as objectName, o.org_name as orgName, o.submit_status as submitStatus, m.assignedCount as reviewerCount, m.submittedCount as submittedCount, greatest(m.assignedCount - m.submittedCount, 0) as unsubmittedCount, concat(m.submittedCount, '/', m.assignedCount) as completionText, case when m.submittedCount = 0 then 'NOT_STARTED' when m.assignedCount > 0 and m.submittedCount >= m.assignedCount then 'COMPLETED' else 'PARTIAL' end as completionStatus, res.calculated_score as calculatedScore, res.calculated_grade as calculatedGrade, res.calculated_rank as calculatedRank, res.evaluation_conclusion as evaluationConclusion, res.result_status as resultStatus, res.generated_time as generatedTime, res.published_time as publishedTime, res.revoked_time as revokedTime from ( select a.activity_id as activityId, a.round_id as roundId, a.object_id as objectId, count(distinct a.id) as assignedCount, count(distinct case when r.id is not null then a.id end) as submittedCount from review_assignment a left join review_record r on r.assignment_id = a.id and r.del_flag = '0' and r.record_status = 'SUBMITTED' and r.total_score is not null where a.del_flag = '0'
and a.activity_id = #{activityId}
and a.round_id = #{roundId}
group by a.activity_id, a.round_id, a.object_id ) m inner join review_object o on o.id = m.objectId and o.del_flag = '0' left join review_activity act on act.id = m.activityId and act.del_flag = '0' left join review_round rd on rd.id = m.roundId and rd.del_flag = '0' left join review_result res on res.activity_id = m.activityId and res.round_id = m.roundId and res.object_id = m.objectId and res.del_flag = '0' where 1 = 1
and o.object_code like concat('%', #{objectCode}, '%')
and o.object_name like concat('%', #{objectName}, '%')
and o.org_name like concat('%', #{orgName}, '%')
and res.result_status = #{resultStatus}
) result_view
completionStatus = #{completionStatus}
order by activityId desc, roundId desc, calculatedRank is null, calculatedRank asc, objectId asc
